schema_ddl:
CREATE TABLE CUSTOMERS (
    ID INT,
    NAME VARCHAR(255),
    PRIMARY KEY (ID)
);

CREATE TABLE ORDERS (
    ID INT,
    CUSTOMERID VARCHAR(255),
    PRIMARY KEY (ID),
    FOREIGN KEY (CUSTOMERID) REFERENCES CUSTOMERS(ID)
);

counterexample:
INSERT INTO CUSTOMERS (ID, NAME) VALUES (1, 'Bob');
INSERT INTO CUSTOMERS (ID, NAME) VALUES (2, 'Alice');
INSERT INTO ORDERS (ID, CUSTOMERID) VALUES (1, '1');
INSERT INTO ORDERS (ID, CUSTOMERID) VALUES (2, '2');

